// Arduino Sketch
// ESP32-S3: ELRS RX (CRSF) -> управление меню VRX Walksnail Ascent + кнопка BIND
// VRX: SETTINGS -> DEVICE -> UART = COMMAND
// ELRS RX: WiFi-меню -> MODEL -> FORCE TELEMETRY OFF

#define PIN_CRSF_RX   4   // TX ELRS-приёмника -> сюда
#define PIN_CRSF_TX   5   // RX ELRS-приёмника -> сюда
#define PIN_VRX_RX    6   // TX VRX (пад «1»)  -> сюда
#define PIN_VRX_TX    7   // RX VRX (пад «2»)  -> сюда
#define PIN_BTN_BIND  8   // кнопка BIND (на GND)
#define PIN_BTN_REC   9   // кнопка RECORD (на GND)

// Индексы каналов CRSF (0 = Ch1)
#define CH_JOY   4        // Ch5  — 5-позиционник: навигация меню
#define CH_BIND  5        // Ch6  — тумблер: дубль BIND (крайнее вверх = команда)
#define CH_REC   6        // Ch7  — тумблер: RECORD
#define CH_BACK  7        // Ch8  — тумблер: BACK (выход из меню)

HardwareSerial Crsf(1);
HardwareSerial Vrx(2);

uint8_t  rxBuf[64];
uint8_t  rxIdx = 0;
uint16_t ch[16];

// ---------- CRSF ----------
uint8_t crc8(const uint8_t *p, uint8_t len) {
  uint8_t crc = 0;
  while (len--) {
    crc ^= *p++;
    for (uint8_t i = 0; i < 8; i++)
      crc = (crc & 0x80) ? (crc << 1) ^ 0xD5 : (crc << 1);
  }
  return crc;
}

void parseCrsf(uint8_t *b) {
  if (b[2] != 0x16) return; // RC_CHANNELS_PACKED
  ch[0] = (b[3]      | b[4] << 8)                        & 0x7FF;
  ch[1] = (b[4] >> 3 | b[5] << 5)                        & 0x7FF;
  ch[2] = (b[5] >> 6 | b[6] << 2 | b[7] << 10)           & 0x7FF;
  ch[3] = (b[7] >> 1 | b[8] << 7)                        & 0x7FF;
  ch[4] = (b[8] >> 4 | b[9] << 4)                        & 0x7FF;
  ch[5] = (b[9] >> 7 | b[10] << 1 | b[11] << 9)          & 0x7FF;
  ch[6] = (b[11] >> 2 | b[12] << 6)                      & 0x7FF;
  ch[7] = (b[12] >> 3 | b[13] << 5)                      & 0x7FF;
}

void crsfPoll() {
  while (Crsf.available()) {
    uint8_t c = Crsf.read();
    if (rxIdx == 0 && c != 0xC8) continue;
    rxBuf[rxIdx++] = c;
    if (rxIdx > 2 && rxIdx == rxBuf[1] + 2) {
      if (crc8(rxBuf + 2, rxBuf[1] - 1) == rxBuf[rxIdx - 1]) parseCrsf(rxBuf);
      rxIdx = 0;
    }
    if (rxIdx >= sizeof(rxBuf)) rxIdx = 0;
  }
}

// ---------- VRX ----------
void vrxSend(uint8_t cmd, const uint8_t *payload, uint8_t len) {
  uint16_t sum = 0;
  Vrx.write(0xFE); Vrx.write(0xEF); Vrx.write(cmd);
  Vrx.write(0x00); Vrx.write(len);
  for (uint8_t i = 0; i < len; i++) { Vrx.write(payload[i]); sum += payload[i]; }
  Vrx.write((sum >> 8) & 0xFF); Vrx.write(sum & 0xFF);
  Vrx.write(0x0D); Vrx.write(0x0A);
}

void vrxKey(uint8_t key, uint8_t arg = 0) {
  uint8_t p[4] = {0x40, key, arg, 0x00};
  vrxSend(0x22, p, 4);
}

// чтение ответов VRX (телеметрия 0x51/0x52)
uint8_t vBuf[32]; uint8_t vIdx = 0;
void vrxPoll() {
  while (Vrx.available()) {
    uint8_t c = Vrx.read();
    if (vIdx == 0 && c != 0xFE) continue;
    vBuf[vIdx++] = c;
    if (vIdx == 4) { if (vBuf[0] != 0xFE || vBuf[1] != 0xEF) vIdx = 0; }
    else if (vIdx >= 5 && vIdx == vBuf[3] * 256 + vBuf[4] + 9) {
      uint8_t *p = vBuf + 5;
      if (p[0] == 0x52) { // RSSI, RSSI2, Mbps, мс, connected
        Serial.printf("RSSI: %d/%d  %d Mbps  %d ms  link:%d\n",
                      (int8_t)p[1], (int8_t)p[2], p[3], p[4], p[5]);
      }
      vIdx = 0;
    }
    if (vIdx >= sizeof(vBuf)) vIdx = 0;
  }
}

// ---------- Кнопки и тумблеры ----------
bool lastBindBtn = true, lastRecBtn = true;
bool lastBindCh = false, lastRecCh = false, lastBackCh = false;

void events() {
  // 5-позиционник: позиция -> клавиша, отправка только при смене позиции
  static uint8_t lastPos = 99;
  uint16_t v = ch[CH_JOY];
  uint8_t pos;
  if      (v < 380)  pos = 0;  // UP
  else if (v < 790)  pos = 1;  // LEFT
  else if (v < 1200) pos = 2;  // ENTER (центр)
  else if (v < 1600) pos = 3;  // RIGHT
  else               pos = 4;  // DOWN
  if (pos != lastPos) {
    static const uint8_t keys[5] = {0x00, 0x02, 0x04, 0x03, 0x01};
    if (lastPos != 99) vrxKey(keys[pos]);
    lastPos = pos;
  }

  // Кнопка BIND: физическая (по фронту) или тумблер с пульта
  bool b = digitalRead(PIN_BTN_BIND);
  if (lastBindBtn && !b) vrxKey(0x05);            // PAIR
  lastBindBtn = b;
  bool bindCh = ch[CH_BIND] > 1400;
  if (bindCh && !lastBindCh) vrxKey(0x05);
  lastBindCh = bindCh;

  // Кнопка RECORD: физическая + тумблер
  bool r = digitalRead(PIN_BTN_REC);
  if (lastRecBtn && !r) vrxKey(0x06);             // RECORD
  lastRecBtn = r;
  bool recCh = ch[CH_REC] > 1400;
  if (recCh && !lastRecCh) vrxKey(0x06);
  lastRecCh = recCh;

  // BACK с тумблера Ch8
  bool bk = ch[CH_BACK] > 1400;
  if (bk && !lastBackCh) vrxKey(0x07);            // BACK
  lastBackCh = bk;
}

void setup() {
  Serial.begin(115200);
  Crsf.begin(115200, SERIAL_8N1, PIN_CRSF_RX, PIN_CRSF_TX);
  Vrx.begin(115200, SERIAL_8N1, PIN_VRX_RX, PIN_VRX_TX);
  pinMode(PIN_BTN_BIND, INPUT_PULLUP);
  pinMode(PIN_BTN_REC, INPUT_PULLUP);
}

void loop() {
  crsfPoll();
  events();
  static uint32_t lastTel = 0;
  if (millis() - lastTel > 200) {                 // статус линка раз в 200 мс
    uint8_t p[8] = {0x52, 0, 0, 0, 0, 0, 0, 0};
    vrxSend(0xA2, p, 8);
    lastTel = millis();
  }
  vrxPoll();
  delay(2);
}

